import {useClickAnalytics} from '@github-ui/use-analytics'
import {useCallback} from 'react'

interface DashboardAnalyticsCallbacks {
  sendDashboardClickAnalyticsEvent: (action: string) => void
}

export function useDashboardAnalytics(): DashboardAnalyticsCallbacks {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const sendDashboardClickAnalyticsEvent = useCallback(
    (action: string) => {
      sendClickAnalyticsEvent({
        category: 'productivity_dashboard',
        action: `click.${action}`,
      })
    },
    [sendClickAnalyticsEvent],
  )

  return {sendDashboardClickAnalyticsEvent}
}
